;
; XCHPUT5 -- docs/bios/CHPUT.md ROUND 5 (2026-11-17): the fourth review's unseparated pairs and cheap
; extensions. The CASE TABLE at the end is GENERATED by probes/bios/spec/xchput5_cases.py (--gen), whose
; docstring documents the setup flags, the record kinds and every group; the same module decodes the run.
; CHPUT called directly; SCREEN 0 width 40; round 4's NEUTRAL setup (no CHPUT / ESC Y places anything).
; Run: python3 -u probes/bios/biosl_run.py probes/bios/spec/xchput5.asm --row nodisk
; The capture: CAP+0 LINLEN, +1 $A5 when finished, +2 CRTCNT, +3 CNSDFG; the records from CAP+4.
;
; CLEAN-ROOM: 100% own code; only published BIOS entries and work-area cells; VRAM through RDVRM / WRTVRM.
;
; @cap C000
; @caplen 12FF
; @timeout 300

RDVRM   equ     $004A
WRTVRM  equ     $004D
INITXT  equ     $006C
CHPUT   equ     $00A2
ERAFNK  equ     $00CC
DSPFNK  equ     $00CF
LINL40  equ     $F3AE
LINLEN  equ     $F3B0
CRTCNT  equ     $F3B1
CSRY    equ     $F3DC
CSRX    equ     $F3DD
CNSDFG  equ     $F3DE
LINTTB  equ     $FBB2
CSRSW   equ     $FCA9

DONE    equ     $C000
CAP     equ     $C001
CAPLEN  equ     4863
ptr     equ     $EF00
tptr    equ     $EF02                   ; the case table pointer
ckey    equ     $EF04
crow    equ     $EF05
ccol    equ     $EF06
cflag   equ     $EF07
ckind   equ     $EF08
clen    equ     $EF09
lasta   equ     $EF0A

                org     $4000
                db      "AB"
                dw      init, 0, 0, 0
                ds      6, 0

init:
                ld      hl, CAP
                ld      de, CAP+1
                ld      bc, CAPLEN - 1
                ld      (hl), 0
                ldir
                ld      a, 40
                ld      (LINL40), a
                call    INITXT
                call    ERAFNK
                ld      a, (LINLEN)
                ld      (CAP+0), a
                ld      a, (CRTCNT)
                ld      (CAP+2), a
                ld      a, (CNSDFG)
                ld      (CAP+3), a
                ld      hl, CAP+4
                ld      (ptr), hl
                ld      hl, cases
                ld      (tptr), hl

next:
                ld      hl, (tptr)
                ld      a, (hl)
                cp      $FF
                jp      z, finish
                ld      de, ckey
                ld      bc, 6
                ldir                            ; key, row, col, flags, kind, length
                ld      (tptr), hl              ; -> the bytes
                ld      a, (ckey)
                or      a
                call    z, ERAFNK
                ld      a, (ckey)
                or      a
                call    nz, DSPFNK
                ld      hl, flush               ; "xx" CR 12, the cursor-display cells 0
                call    puts
                xor     a
                ld      (CSRSW), a
                ld      (CSRSW+1), a
                call    mark3
                ld      a, (cflag)
                and     1
                call    nz, markpqr
                ld      a, (cflag)
                and     2
                call    nz, markkey
                ld      a, (cflag)
                and     4
                jr      z, nf4
                xor     a
                ld      (LINTTB+11), a
                ld      (LINTTB+12), a
nf4:
                ld      a, (cflag)
                and     8
                jr      z, nf8
                ld      a, 1
                ld      (CSRSW), a
                ld      (CSRSW+1), a
nf8:
                ld      a, (crow)
                inc     a
                ld      (CSRY), a
                ld      a, (ccol)
                inc     a
                ld      (CSRX), a
                ; send the bytes (kind 2, SEQ: the cursor after every byte)
                ld      a, (clen)
                ld      b, a
send:
                ld      hl, (tptr)
                ld      a, (hl)
                inc     hl
                ld      (tptr), hl
                push    bc
                call    CHPUT
                ld      (lasta), a
                ld      a, (ckind)
                cp      2
                call    z, cur
                pop     bc
                djnz    send
                ; record by kind
                ld      a, (ckind)
                or      a
                jr      z, k_cur
                dec     a
                jr      z, k_xy
                dec     a
                jr      z, k_seq
                dec     a
                jr      z, k_key
                dec     a
                jp      z, k_edit
                ; kind 5, TAB: cursor, LINTTB[22], [23], cells (22,0) (22,39) (23,0) (23,39) (0,0)
                call    cur
                ld      a, (LINTTB+22)
                call    emit
                ld      a, (LINTTB+23)
                call    emit
                ld      de, 22*256 + 0
                call    vre
                ld      e, 39
                call    vre
                ld      de, 23*256 + 0
                call    vre
                ld      e, 39
                call    vre
                ld      de, 0
                call    vre
                jp      next
k_cur:
                call    cur
                ld      de, 10*256 + 18
kc_lp:
                call    vre
                inc     e
                ld      a, e
                cp      23
                jr      nz, kc_lp
                jp      next
k_xy:
                ld      a, (CSRSW)
                call    emit
                ld      a, (CSRSW+1)
                call    emit
                jp      next
k_seq:
                ld      de, 5*256 + 0
                call    vre
                inc     e
                call    vre
                inc     e
                call    vre
                ld      de, 23*256 + 0
                call    vre
                inc     e
                call    vre
                inc     e
                call    vre
                jp      next
k_key:
                call    cur
                ld      de, 23*256 + 0
                call    vre
                inc     e
                call    vre
                ld      e, 38
                call    vre
                inc     e
                call    vre
                jp      next
k_edit:
                call    cur
                ld      hl, LINTTB
                ld      b, 24
ke_lt:
                ld      a, (hl)
                call    emit
                inc     hl
                djnz    ke_lt
                ld      d, 0
ke_row:
                ld      e, 0
                call    vre
                ld      e, 39
                call    vre
                inc     d
                ld      a, d
                cp      24
                jr      nz, ke_row
                jp      next

finish:
                call    ERAFNK
                ld      hl, tidy
                call    puts
                ld      a, $A5
                ld      (CAP+1), a
                ld      (DONE), a
halt_lp:
                jr      halt_lp

; mark3 -- columns 0 / 38 / 39 of every TEXT row r: 'a'+r, 'A'+r, '0'+r (VRAM directly)
mark3:
                ld      a, (CNSDFG)
                or      a
                ld      b, 24
                jr      z, m3_n
                ld      b, 23
m3_n:
                ld      d, 0
m3_lp:
                push    bc
                ld      e, 0
                ld      a, d
                add     a, 'a'
                call    vw
                ld      e, 38
                ld      a, d
                add     a, 'A'
                call    vw
                ld      e, 39
                ld      a, d
                add     a, '0'
                call    vw
                pop     bc
                inc     d
                djnz    m3_lp
                ret

; markpqr -- P Q R at (10, 19..21)
markpqr:
                ld      de, 10*256 + 19
                ld      a, 'P'
                call    vw
                inc     e
                ld      a, 'Q'
                call    vw
                inc     e
                ld      a, 'R'
                jp      vw

; markkey -- the key row's columns 0, 1, 38, 39 := K L M N
markkey:
                ld      de, 23*256 + 0
                ld      a, 'K'
                call    vw
                inc     e
                ld      a, 'L'
                call    vw
                ld      e, 38
                ld      a, 'M'
                call    vw
                inc     e
                ld      a, 'N'
                jp      vw

; vre -- emit the VRAM cell at (D, E). Keeps DE.
vre:
                call    vr
                jp      emit

; vw -- the VRAM cell at (D = row, E = column) := A. Keeps DE.
vw:
                push    af
                call    vaddr
                pop     af
                push    de
                call    WRTVRM
                pop     de
                ret

; vr -- A := the VRAM cell at (D = row, E = column). Keeps DE.
vr:
                call    vaddr
                push    de
                call    RDVRM
                pop     de
                ret

; vaddr -- HL := D * 40 + E. Keeps DE.
vaddr:
                push    de
                ld      l, d
                ld      h, 0
                add     hl, hl
                add     hl, hl
                add     hl, hl
                push    hl
                add     hl, hl
                add     hl, hl
                pop     bc
                add     hl, bc
                ld      d, 0
                add     hl, de
                pop     de
                ret

emit:
                push    hl
                ld      hl, (ptr)
                ld      (hl), a
                inc     hl
                ld      (ptr), hl
                pop     hl
                ret

cur:
                ld      a, (CSRX)
                call    emit
                ld      a, (CSRY)
                jp      emit

puts:
                ld      a, (hl)
                or      a
                ret     z
                push    hl
                call    CHPUT
                pop     hl
                inc     hl
                jr      puts

flush:          db      "xx", 13, 12, 0
tidy:           db      "xx", 13, 10, 0

